from itertools import product
from fractions import Fraction
import json

# Partitions padded to five parts, reverse lexicographic order as requested.
def parts_weight(n, maxpart=5, length=5):
    out=[]
    def rec(rem, prev, a):
        if len(a)==length:
            if rem==0: out.append(tuple(a))
            return
        for x in range(min(prev,maxpart,rem),-1,-1): rec(rem-x,x,a+[x])
    rec(n,maxpart,[])
    return sorted(out, reverse=True)
def weight(p): return sum(p)
def inJ(p): return p[0]>=3 and p[1]>=3 and p[2]>=3 and p[0]<=5
def horiz(lam,mu,t):
    # mu/lam horizontal t-strip: containment and every column increases by at most one.
    if weight(mu)-weight(lam)!=t or any(lam[i]>mu[i] for i in range(5)): return False
    def col(p,c): return sum(x>=c for x in p)
    return all(0 <= col(mu,c)-col(lam,c) <= 1 for c in range(1,6))
def conjugate2(rho):
    return tuple(sum(x>=c for x in rho) for c in range(1,4))
def rshape(rp):
    return tuple(3+rp[i] for i in range(3))+(0,0)
def lshape(rho): return (3,3,3)+tuple(rho)
def rhos():
    return [p[:2] for p in parts_weight(0,3,2)] # unused
# partitions in 3^2, exactly two rows
RR=[]
for n in range(7):
    for a in range(3,-1,-1):
        b=n-a
        if 0<=b<=a and b<=3: RR.append((a,b))
RR=sorted(set(RR), key=lambda x:(sum(x),x), reverse=False)

def rref_solve(A,b):
    # A m x n, solve A x=b, free variables zero; returns rational x or None
    M=[[Fraction(x) for x in row]+[Fraction(bb)] for row,bb in zip(A,b)]
    m=len(M); n=len(A[0]) if m else 0; piv=[]; r=0
    for c in range(n):
        q=next((i for i in range(r,m) if M[i][c]),None)
        if q is None: continue
        M[r],M[q]=M[q],M[r]
        z=M[r][c]; M[r]=[v/z for v in M[r]]
        for i in range(m):
            if i!=r and M[i][c]:
                z=M[i][c]; M[i]=[M[i][j]-z*M[r][j] for j in range(n+1)]
        piv.append(c); r+=1
        if r==m: break
    if any(all(M[i][c]==0 for c in range(n)) and M[i][n]!=0 for i in range(m)): return None
    x=[Fraction(0) for _ in range(n)]
    for i,c in enumerate(piv): x[c]=M[i][n]
    return x

records={}
all_targets=[]
for d in range(9,16):
    cols=[p for p in parts_weight(d) if inJ(p)]
    rows=[]; mat=[]
    for t in range(1,6):
        for lam in [p for p in parts_weight(d-t) if inJ(p)]:
            row=[1 if horiz(lam,mu,t) else 0 for mu in cols]
            rows.append((t,lam)); mat.append(row)
    records[d]={"columns":[list(x) for x in cols],"rows":[[t,list(p)] for t,p in rows],"matrix":mat}
for rho in RR:
    d=9+sum(rho); rec=records[d]; cols=[tuple(x) for x in rec['columns']]; mat=rec['matrix']
    rp=conjugate2(rho)
    R=rshape(rp); L=lshape(rho)
    target=[(1 if c==R else 0) - ((-1)**sum(rho))*(1 if c==L else 0) for c in cols]
    # mat transpose times coefficient vector = target
    A=[[mat[j][i] for j in range(len(mat))] for i in range(len(cols))]
    sol=rref_solve(A,target)
    if sol is None: raise RuntimeError(('no rational solution',rho))
    if any(x.denominator!=1 for x in sol):
        raise RuntimeError(('nonintegral default solution',rho,[str(x) for x in sol]))
    combo=[]
    for coeff,label in zip(sol,rec['rows']):
        if coeff: combo.append([int(coeff),label])
    verify=[sum(int(sol[j])*mat[j][i] for j in range(len(mat))) for i in range(len(cols))]
    if verify!=target: raise RuntimeError(('verify',rho))
    all_targets.append({"rho":list(rho),"rhoPrime":list(rp),"degree":d,"R":list(R),"L":list(L),"sign":(-1)**sum(rho),"target":target,"combination":combo,"verified":True})
print(json.dumps({"definition":{"A":"Lambda/I_{5,5}","J":"direct sum over 333 subseteq lambda subseteq 5^5 of Z bar{s}_lambda","pieri":"h_t bar{s}_lambda=sum bar{s}_mu over mu/lambda horizontal t-strip and mu subseteq 5^5"},"ordering":"columns and source partitions are padded length-5 partitions, decreasing lexicographic; rows grouped by t=1,2,3,4,5 then source order","matrices":records,"identities":all_targets},separators=(',',':')))
